using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class B1Details {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static void Shot(string file,Vector3 pos,Vector3 target){var g=new GameObject("B1_TemporaryDetailCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.useOcclusionCulling=false;c.fieldOfView=55;c.nearClipPlane=.02f;c.farClipPlane=260;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1280,960,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1280,960,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,960),0,0);tex.Apply();File.WriteAllBytes(R+"/Docs/Review/2026-11-11_B1_FullFloor/"+file+".jpg",tex.EncodeToJPG(90));}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 only");var root=GameObject.Find("B1_ResearchAndStaffFloor");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B1_FullFloor/layout.json"));int count=0;try{var wanted=new[]{"BL_","SD_CentrifugeBench","SF_SC_OperatorDesk_A","SF_MedicalBed","SF_DoubleWashSink","LB_SensorPrepBench"};foreach(var p in plan["placements"].GroupBy(p=>(string)p["model"]).Select(g=>g.First()).Where(p=>wanted.Any(n=>((string)p["model"]).StartsWith(n)))){var t=root.transform.Find("B1_"+(string)p["room"]+"_Sector/Equipment/"+(string)p["name"]);var size=new Vector3((float)p["size"][0],(float)p["size"][1],(float)p["size"][2]);var center=t.TransformPoint(new Vector3((float)p["center"][0],(float)p["center"][1],(float)p["center"][2]));float dist=Mathf.Max(size.x,size.y,size.z)*1.55f;var dir=t.TransformDirection(new Vector3(.5f,.30f,1).normalized);Shot("detail_"+(string)p["model"],center+dir*dist,center);count++;}}finally{EditorSceneManager.OpenScene(s.path);}return new{closeups=count};}
}
